/// Set or replace an organization's logo, by uploading an image file. This endpoint uses the `multipart/form-data` request content type and accepts a file of image type. The file size cannot exceed 10MB. Only the following file content types are supported: `image/jpeg`, `image/png`, `image/gif`, `image/webp`.
pub async fn upload_organization_logo(
	configuration: &configuration::Configuration,
	organization_id: &str,
	file: std::path::PathBuf,
	uploader_user_id: Option<&str>,
) -> Result<models::OrganizationWithLogo, Error<UploadOrganizationLogoError>> {
	// add a prefix to parameters to efficiently prevent name collisions
	let p_path_organization_id = organization_id;
	let p_form_file = file;
	let p_form_uploader_user_id = uploader_user_id;

	let uri_str = format!(
		"{}/organizations/{organization_id}/logo",
		configuration.base_path,
		organization_id = crate::apis::urlencode(p_path_organization_id)
	);
	let mut req_builder = configuration.client.request(reqwest::Method::PUT, &uri_str);

	if let Some(ref user_agent) = configuration.user_agent {
		req_builder = req_builder.header(reqwest::header::USER_AGENT, user_agent.clone());
	}
	if let Some(ref token) = configuration.bearer_access_token {
		req_builder = req_builder.bearer_auth(token.to_owned());
	};
	let mut multipart_form = reqwest::multipart::Form::new();
	if let Some(param_value) = p_form_uploader_user_id {
		multipart_form = multipart_form.text("uploader_user_id", param_value.to_string());
	}
	let file = TokioFile::open(&p_form_file).await?;
	let stream = FramedRead::new(file, BytesCodec::new());
	let file_name = p_form_file.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
	let file_part = reqwest::multipart::Part::stream(reqwest::Body::wrap_stream(stream)).file_name(file_name);
	multipart_form = multipart_form.part("file", file_part);
	req_builder = req_builder.multipart(multipart_form);

	let req = req_builder.build()?;
	let resp = configuration.client.execute(req).await?;

	let status = resp.status();
	let content_type = resp
		.headers()
		.get("content-type")
		.and_then(|v| v.to_str().ok())
		.unwrap_or("application/octet-stream");
	let content_type = super::ContentType::from(content_type);

	if !status.is_client_error() && !status.is_server_error() {
		let content = resp.text().await?;
		match content_type {
			ContentType::Json => serde_json::from_str(&content).map_err(Error::from),
			ContentType::Text => {
				return Err(Error::from(serde_json::Error::custom(
					"Received `text/plain` content type response that cannot be converted to `models::OrganizationWithLogo`",
				)))
			}
			ContentType::Unsupported(unknown_type) => {
				return Err(Error::from(serde_json::Error::custom(format!(
					"Received `{unknown_type}` content type response that cannot be converted to `models::OrganizationWithLogo`"
				))))
			}
		}
	} else {
		let content = resp.text().await?;
		let entity: Option<UploadOrganizationLogoError> = serde_json::from_str(&content).ok();
		Err(Error::ResponseError(ResponseContent { status, content, entity }))
	}
}
